3	//  Replog
4	//
5	//  The daily hub: greeting + streak, week strip, today's workout hero, a scroller
6	//  of other workouts to run as extras, quick stats, and the latest PR.
7	//
8	
9	import SwiftUI
10	import SwiftData
11	
12	struct TodayView: View {
13	    @Environment(\.modelContext) private var context
14	    @Environment(\.exerciseCatalog) private var catalog
15	    @Query(sort: \Plan.order) private var plans: [Plan]
16	    @Query private var profiles: [UserProfile]
17	    @Query private var history: [HistoryEntry]
18	    @Query private var activeSessions: [ActiveSession]
19	
20	    @State private var path = NavigationPath()
21	    @State private var selectedStat: StatKind?
22	
23	    private var profile: UserProfile { profiles.first ?? context.userProfile() }
24	
25	    /// A paused/in-progress session, if any (one at a time).
26	    private var activeSession: ActiveSession? { activeSessions.first }
27	
28	    private var scheduledDays: Set<Weekday> { StreakEngine.scheduledDays(in: plans) }
29	
30	    /// All workouts across all plans.
31	    private var allWorkouts: [Workout] {
32	        plans.flatMap(\.orderedWorkouts)
33	    }
34	
35	    /// The workout scheduled for today's weekday (if any).
36	    private var todaysWorkout: Workout? {
37	        let today = Weekday.from(Date())
38	        return allWorkouts.first { $0.day == today }
39	    }
40	
41	    private var otherWorkouts: [Workout] {
42	        allWorkouts.filter { $0.id != todaysWorkout?.id }
43	    }
44	
45	    private var streak: Int {
46	        StreakEngine.workoutStreak(scheduledDays: scheduledDays, doneDates: profile.doneDates)
47	    }
48	
49	    private var weekStreak: Int {
50	        StreakEngine.weekStreak(scheduledDays: scheduledDays, doneDates: profile.doneDates)
51	    }
52	
53	    var body: some View {
54	        NavigationStack(path: $path) {
55	            ScrollView {
56	                VStack(alignment: .leading, spacing: 22) {
57	                    header
58	                    WeekStripView(cells: StreakCalendar.weekStrip(doneDates: profile.doneDates))
59	
60	                    if let session = activeSession {
61	                        resumeBanner(session)
62	                    }
63	
64	                    if let workout = todaysWorkout {
65	                        SectionHeader(title: "Today's Workout")
66	                        TodayHeroCard(workout: workout, catalog: catalog,
67	                                      isResuming: isActive(workout)) { start(workout) }
68	                    } else {
69	                        SectionHeader(title: "Today")
70	                        restDayCard
71	                    }
72	
73	                    if !otherWorkouts.isEmpty {
74	                        VStack(alignment: .leading, spacing: 4) {
75	                            SectionHeader(title: "Add Another Workout")
76	                            Text("Train extra today — won't change your schedule")
77	                                .font(.rounded(13, .semibold))
78	                                .foregroundStyle(Color.text3)
79	                        }
80	                        addAnotherScroller
81	                    }
82	
83	                    quickStats
84	                    if let highlight = recentHighlight { highlight }
85	                }
86	                .padding(20)
87	            }
88	            .background(Color.bg.ignoresSafeArea())
89	            .toolbar(.hidden, for: .navigationBar)
90	            .planNavigationDestinations()
91	            .sheet(item: $selectedStat) { kind in
92	                StatDetailSheet(kind: kind, doneDates: profile.doneDates, history: history,
93	                                catalog: catalog, scheduledCount: scheduledDays.count,
94	                                workoutStreakValue: streak, weekStreakValue: weekStreak,
95	                                totalWorkouts: profile.totalWorkouts)
96	            }
97	        }
98	    }
99	
100	    // MARK: Header
101	
102	    private var header: some View {
103	        HStack(alignment: .top) {
104	            VStack(alignment: .leading, spacing: 2) {
105	                Text(greeting).eyebrow()
106	                Text(profile.name).font(.screenTitle).foregroundStyle(Color.textPrimary)
107	            }
108	            Spacer()
109	            HStack(spacing: 5) {
110	                Image(systemName: "flame.fill").font(.system(size: 15, weight: .bold))
111	                    .foregroundStyle(Color.accent)
112	                Text("\(streak)").font(.rounded(16, .black)).foregroundStyle(Color.textPrimary)
113	            }
114	            .padding(.horizontal, 12).padding(.vertical, 8)
115	            .background(Capsule().fill(Color.surface))
116	            .overlay(Capsule().strokeBorder(Color.border, lineWidth: 1))
117	        }
118	    }
119	
120	    private var greeting: String {
121	        switch Calendar.current.component(.hour, from: Date()) {
122	        case 0..<12: return "Good morning"
123	        case 12..<17: return "Good afternoon"
124	        default: return "Good evening"
125	        }
126	    }
127	
128	    // MARK: Add another
129	
130	    private var addAnotherScroller: some View {
131	        ScrollView(.horizontal, showsIndicators: false) {
132	            HStack(spacing: 12) {
133	                ForEach(otherWorkouts) { workout in
134	                    OtherWorkoutCard(workout: workout, isResuming: isActive(workout)) { start(workout) }
135	                }
136	                NewWorkoutCard { createPlanAndOpen() }
137	            }
138	        }
139	    }
140	
141	    private func createPlanAndOpen() {
142	        let plan = PlanFactory.emptyPlan(into: context, order: plans.count)
143	        try? context.save()
144	        path.append(plan)
145	    }
146	
147	    // MARK: Stats
148	
149	    private var thisWeekCount: Int {
150	        profile.doneDates.filter { Calendar.current.isDate($0, equalTo: Date(), toGranularity: .weekOfYear) }.count
151	    }
152	
153	    private var quickStats: some View {
154	        HStack(spacing: 12) {
155	            StatCard(value: "\(weekStreak)", label: "Week streak") { selectedStat = .weekStreak }
156	            StatCard(value: "\(thisWeekCount)", label: "This week") { selectedStat = .thisWeek }
157	            StatCard(value: "\(profile.totalWorkouts)", label: "Workouts") { selectedStat = .workouts }
158	        }
159	    }
160	
161	    @ViewBuilder
162	    private func resumeBanner(_ session: ActiveSession) -> some View {
163	        Button {
164	            session.isOpen = true
165	            try? context.save()
166	        } label: {
167	            HStack(spacing: 12) {
168	                Image(systemName: "figure.strengthtraining.traditional")
169	                    .font(.system(size: 18, weight: .bold)).foregroundStyle(.white)
170	                    .frame(width: 40, height: 40)
171	                    .background(Circle().fill(Color.accent))
172	                VStack(alignment: .leading, spacing: 2) {
173	                    Text("Workout in progress").eyebrow()
174	                    Text(session.name).font(.cardTitle).foregroundStyle(Color.textPrimary)
175	                }
176	                Spacer()
177	                Text("Continue").font(.rounded(14, .heavy)).foregroundStyle(.white)
178	                    .padding(.horizontal, 14).padding(.vertical, 8)
179	                    .background(Capsule().fill(Color.accent))
180	            }
181	            .padding(14)
182	            .cardSurface(fill: Color.accentSoft)
183	        }
184	        .buttonStyle(.plain)
185	    }
186	
187	    private func isActive(_ workout: Workout) -> Bool {
188	        activeSession?.workoutId == workout.id
189	    }
190	
191	    private var recentHighlight: (some View)? {
192	        guard let best = history.max(by: { $0.e1rm < $1.e1rm }),
193	              let ex = catalog.exercise(id: best.exId) else { return Optional<AnyView>.none }
194	        return AnyView(
195	            VStack(alignment: .leading, spacing: 8) {
196	                SectionHeader(title: "Recent Highlight")
197	                HStack(spacing: 12) {
198	                    ExerciseThumbnail(exercise: ex, size: 48, cornerRadius: 12)
199	                    VStack(alignment: .leading, spacing: 2) {
200	                        Text(ex.name).font(.cardTitle).foregroundStyle(Color.textPrimary)
201	                        Text("\(best.e1rm) est. 1RM").font(.rounded(13, .bold)).foregroundStyle(Color.accent)
202	                    }
203	                    Spacer()
204	                    Image(systemName: "trophy.fill").foregroundStyle(Color.accent)
205	                }
206	                .padding(14)
207	                .cardSurface()
208	            }
209	        )
210	    }
211	
212	    private var restDayCard: some View {
