15	    static func e1rm(kg: Double, reps: Int) -> Double {
16	        guard reps > 0 else { return 0 }
17	        return kg * (1 + Double(reps) / 30)
18	    }
19	
20	    /// Integer estimated 1RM for display/storage.
21	    static func e1rmRounded(kg: Double, reps: Int) -> Int {
22	        Int(e1rm(kg: kg, reps: reps).rounded())
23	    }
24	
25	    /// Converts kg to lb, rounded to the nearest 5 lb (matches the +5 lb stepper).
26	    static func kgToLb(_ kg: Double) -> Double {
27	        let lb = kg * 2.20462
28	        return (lb / 5).rounded() * 5
29	    }
30	
31	    /// Converts a nearest-5 lb value back to kg (for editing in lb).
32	    static func lbToKg(_ lb: Double) -> Double {
33	        lb / 2.20462
34	    }
35	
36	    /// Stepper increment for weight in the user's display unit, expressed in kg.
37	    /// +2.5 kg when displaying kg; +5 lb (≈2.2679 kg) when displaying lb.
38	    static func weightStepKg(units: Units) -> Double {
39	        switch units {
40	        case .kg: return 2.5
41	        case .lb: return lbToKg(5)
42	        }
43	    }
44	
45	    /// The displayed weight value for a kg amount in the chosen units.
46	    static func displayWeight(kg: Double, units: Units) -> Double {
47	        switch units {
48	        case .kg: return kg
49	        case .lb: return kgToLb(kg)
50	        }
51	    }
52	
53	    /// Formats a weight for display, dropping a trailing ".0" and appending the unit.
54	    static func formatWeight(kg: Double, units: Units, includeUnit: Bool = true) -> String {
55	        let value = displayWeight(kg: kg, units: units)
56	        let text: String = value == value.rounded()
57	            ? String(Int(value))
58	            : String(format: "%.1f", value)
59	        return includeUnit ? "\(text)\(units.label)" : text
60	    }
61	
62	    /// Parses user-typed weight text (entered in `units`) into clamped kilograms.
63	    /// Accepts "," or "." decimals; returns nil when the text isn't a number.
64	    static func parseWeightKg(_ raw: String, units: Units) -> Double? {
65	        let normalized = raw.replacingOccurrences(of: ",", with: ".")
66	            .trimmingCharacters(in: .whitespaces)
67	        guard let value = Double(normalized) else { return nil }
68	        let kg = units == .kg ? value : lbToKg(value)
69	        return max(0, kg)
70	    }
71	
72	    /// Parses user-typed reps text into a clamped positive integer (nil if non-numeric).
73	    static func parseReps(_ raw: String) -> Int? {
74	        guard let value = Int(raw.filter(\.isNumber)) else { return nil }
75	        return max(1, value)
76	    }
77	}
