//
//  Sparkline.swift
//  Replog
//
//  A tiny inline trend line for Progress rows. Pure Path drawing (cheap).
//

import SwiftUI

struct Sparkline: View {
    let values: [Int]
    var color: Color = .accent

    var body: some View {
        GeometryReader { geo in
            if values.count >= 2 {
                line(in: geo.size)
                    .stroke(color, style: StrokeStyle(lineWidth: 2, lineCap: .round, lineJoin: .round))
            } else {
                // Flat baseline for sparse data.
                Path { p in
                    p.move(to: CGPoint(x: 0, y: geo.size.height / 2))
                    p.addLine(to: CGPoint(x: geo.size.width, y: geo.size.height / 2))
                }
                .stroke(color.opacity(0.4), style: StrokeStyle(lineWidth: 2, lineCap: .round))
            }
        }
    }

    private func line(in size: CGSize) -> Path {
        let minV = values.min() ?? 0
        let maxV = values.max() ?? 1
        let range = max(1, maxV - minV)
        let stepX = size.width / CGFloat(values.count - 1)

        return Path { p in
            for (i, v) in values.enumerated() {
                let x = CGFloat(i) * stepX
                let y = size.height - (CGFloat(v - minV) / CGFloat(range)) * size.height
                if i == 0 { p.move(to: CGPoint(x: x, y: y)) }
                else { p.addLine(to: CGPoint(x: x, y: y)) }
            }
        }
    }
}

//
//  DebugSeed.swift
//  Replog
//
//  DEBUG-only helpers to launch straight into a populated app for visual checks.
//  Driven by launch environment variables (never used in Release):
//    REPLOG_SEED=1     -> seed a demo plan + history and mark onboarding done
//    REPLOG_TAB=<name> -> initial tab (today|plans|library|progress|profile)
//

import Foundation
import SwiftData

#if DEBUG
@MainActor
enum DebugSeed {
    static var isSeedRequested: Bool {
        ProcessInfo.processInfo.environment["REPLOG_SEED"] == "1"
    }

    static var initialTab: MainTabView.Tab? {
        switch ProcessInfo.processInfo.environment["REPLOG_TAB"] {
        case "plans": return .plans
        case "library": return .library
        case "progress": return .progress
        case "profile": return .profile
        case "today": return .today
        default: return nil
        }
    }

    /// Seeds a demo plan + a little history if the store is empty.
    static func seedIfNeeded(_ context: ModelContext) {
        guard isSeedRequested else { return }
        let profile = context.userProfile()
        if ProcessInfo.processInfo.environment["REPLOG_DARK"] == "1" {
            context.appSettings().darkMode = true
            try? context.save()
        }
        guard !profile.onboardingDone else { return }

        var answers = QuizAnswers()
        answers.firstName = "Alex"
        answers.daysPerWeek = 3
        let generated = PlanGenerator().generate(answers)
        let report = ReportComposer.fallbackMarkdown(answers: answers, plan: generated)
        let plan = PlanFactory.insert(generated, into: context, order: 0, reportMarkdown: report)

        // Fabricate a few weeks of history for the first exercise to populate Progress.
        if let firstItem = plan.orderedWorkouts.first?.orderedItems.first {
            let exId = firstItem.exId
            let cal = Calendar.current
            for (i, e1rm) in [92, 96, 99, 104, 110].enumerated() {
                let date = cal.date(byAdding: .day, value: -(28 - i * 7), to: Date()) ?? Date()
                let entry = HistoryEntry(exId: exId, date: date, topW: Double(70 + i * 2), topR: 8,
                                         e1rm: e1rm, sets: [RecordedSet(w: Double(70 + i * 2), r: 8),
                                                            RecordedSet(w: 60, r: 10)])
                context.insert(entry)
            }
        }

        profile.name = "Alex"
        profile.streak = 3
        profile.weekStreak = 2
        profile.totalWorkouts = 12
        profile.doneDates = StreakCalendar.recordingCompletion(Date(), into: [])
        profile.onboardingDone = true
        try? context.save()

        // Optionally drop straight into a live workout for verification.
        if ProcessInfo.processInfo.environment["REPLOG_ACTIVE"] == "1",
           let workout = plan.orderedWorkouts.first {
            let session = SessionBuilder.start(workout: workout, into: context)
            if ProcessInfo.processInfo.environment["REPLOG_COMPLETE"] == "1" {
                // Mark everything done to preview the completion celebration.
                session.exercises.forEach { $0.sets.forEach { $0.done = true } }
            } else if let firstSet = session.orderedExercises.first?.orderedSets.first {
                // Mark the first exercise's first set done so the "crossing" state is visible.
                firstSet.done = true
            }
            try? context.save()
        }
    }
}
#endif

//
//  SetRestSheet.swift
//  Replog
//
//  Bulk "set rest for all exercises / whole plan" — a +/- (and typeable) counter that
//  matches Profile's Rest duration control, instead of a preset dropdown.
//

import SwiftUI

struct SetRestSheet: View {
    let title: String
    let initialSeconds: Int
    /// `nil` = use the app default for every exercise.
    let onApply: (Int?) -> Void

    @Environment(\.dismiss) private var dismiss
    @State private var seconds: Int

    init(title: String, initialSeconds: Int, onApply: @escaping (Int?) -> Void) {
        self.title = title
        self.initialSeconds = max(5, initialSeconds)
        self.onApply = onApply
        _seconds = State(initialValue: max(5, initialSeconds))
    }

    var body: some View {
        NavigationStack {
            VStack(alignment: .leading, spacing: 18) {
                Text("Sets the rest between sets for every exercise here. Overrides each exercise's own rest.")
                    .font(.rounded(13, .semibold)).foregroundStyle(Color.text3)
                    .fixedSize(horizontal: false, vertical: true)

                HStack(spacing: 12) {
                    Image(systemName: "clock.arrow.circlepath")
                        .font(.system(size: 16, weight: .bold)).foregroundStyle(Color.accent)
                        .frame(width: 36, height: 36)
                        .background(RoundedRectangle(cornerRadius: 10, style: .continuous).fill(Color.accentSoft))
                    Text("Rest duration").font(.rounded(15, .heavy)).foregroundStyle(Color.textPrimary)
                    Spacer()
                    NumericStepperField(display: "\(seconds)", keyboard: .numberPad,
                                        onMinus: { seconds = max(5, seconds - 15) },
                                        onPlus: { seconds = min(600, seconds + 15) },
                                        onCommit: { if let v = Int($0.filter(\.isNumber)) { seconds = min(600, max(5, v)) } })
                    Text("sec").font(.rounded(11, .bold)).foregroundStyle(Color.text3)
                }
                .padding(14)
                .cardSurface()

                PrimaryButton(title: "Apply to all") { onApply(seconds); dismiss() }
                Button("Use app default") { onApply(nil); dismiss() }
                    .font(.rounded(14, .heavy)).foregroundStyle(Color.text2)
                    .frame(maxWidth: .infinity)
                Spacer(minLength: 0)
            }
            .padding(20)
            .background(Color.bg.ignoresSafeArea())
            .navigationTitle(title)
            .navigationBarTitleDisplayMode(.inline)
            .hideKeyboardOnTap()
        }
        .presentationDetents([.height(340)])
        .presentationDragIndicator(.visible)
    }
}

