//
//  TrendCalculator.swift
//  Replog
//
//  Finance-style up/down/flat comparison of a logged value against the same set
//  index from the previous session.
//

import Foundation

enum TrendCalculator {
    /// Compares a current value to a previous one.
    /// `nil` previous (no prior session) yields `.none` (no arrow shown).
    static func trend(current: Double, previous: Double?) -> Trend {
        guard let previous else { return .none }
        if current > previous { return .up }
        if current < previous { return .down }
        return .flat
    }

    /// Percentage change current vs previous, or nil when there's no baseline.
    static func percentChange(current: Double, previous: Double?) -> Double? {
        guard let previous, previous != 0 else { return nil }
        return (current - previous) / previous * 100
    }
}

//
//  History.swift
//  Replog
//
//  Per-exercise progression history, appended on Finish. Drives Progress charts,
//  trend %, and the "previous" reference for the next session's logging.
//

import Foundation
import SwiftData

/// One recorded set (weight x reps) within a history entry.
struct RecordedSet: Codable, Hashable, Sendable {
    var w: Double
    var r: Int
}

@Model
final class HistoryEntry {
    var id: UUID = UUID()
    /// References `Exercise.id` in the static catalog.
    var exId: String = ""
    var date: Date = Date()
    var topW: Double = 0
    var topR: Int = 0
    var e1rm: Int = 0
    /// JSON-encoded `[RecordedSet]` of every set done that day (for the Session Log).
    var setsJSON: String = "[]"

    init(exId: String, date: Date, topW: Double, topR: Int, e1rm: Int, sets: [RecordedSet]) {
        self.exId = exId
        self.date = date
        self.topW = topW
        self.topR = topR
        self.e1rm = e1rm
        self.sets = sets
    }

    /// Decoded sets done that day.
    var sets: [RecordedSet] {
        get { (try? JSONDecoder().decode([RecordedSet].self, from: Data(setsJSON.utf8))) ?? [] }
        set { setsJSON = String(data: (try? JSONEncoder().encode(newValue)) ?? Data("[]".utf8), encoding: .utf8) ?? "[]" }
    }
}

