import Foundation
import SwiftData

@Model
final class BodyweightEntry {
    var id: UUID = UUID()
    var date: Date = Date()
    /// Stored in kilograms; display conversion happens at the edge (`Formulas`).
    var weightKg: Double = 0

    init(weightKg: Double, date: Date = Date()) {
        self.weightKg = weightKg
        self.date = date
    }
}

