        // ±0.1 kg wobble around 75 — a real scale never repeats exactly.
        let snap = try #require(BodyweightTracker.snapshot(
            entries: entries([(-21, 75.1), (-14, 74.9), (-7, 75.1), (0, 75.0)])))
        #expect(snap.direction == .flat)
    }

